async function readPhoto(file){if(!file)return;if(file.size>20*1024*1024)return toast('圖片太大，請選較小的照片');try{const original=await compress(file);$('originalPhotoData').value=original;$('photoData').value=original;$('photoPreview').innerHTML='<img src="'+original+'" alt="名片照片預覽">';$('removePhotoBtn').classList.remove('hidden');$('ocrBtn').classList.remove('hidden');setOcrProgress(.08,'原始照片已保留，正在裁切名片…');await new Promise(r=>setTimeout(r,20));const crop=await fastAutoCropCard(original).catch(()=>({dataUrl:original,cropped:false})),d=crop.dataUrl;$('photoData').value=d;$('photoPreview').innerHTML='<img src="'+d+'" alt="名片裁切預覽">';$('photoPreserveStatus').classList.remove('hidden');$('photoPreserveStatus').innerHTML='<span>✓ 原始照片已保留</span><span>'+(crop.cropped?'✓ 已自動裁切名片':'• 未偵測到明確邊界，先保留原圖')+'</span>';$('ocrProgress').classList.add('hidden');toast(crop.cropped?'原圖已保留，名片也已自動裁切':'原圖已保留，這張先使用原始照片');if(currentMode==='scan')setTimeout(runOCR,80)}catch(e){console.error(e);$('ocrProgress').classList.add('hidden');toast('照片讀取失敗')}}
