function ocrScore(raw){let s=0;if(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(raw))s+=5;if(/(?:\+?\d[\d\s().-]{7,}\d)/.test(raw))s+=4;if(/[\u3400-\u9fff]{2,}/.test(raw))s+=3;if(/(公司|有限公司|Inc\.?|Ltd\.?|Corp\.?|Group|Manager|經理|工程師|主任|科長)/i.test(raw))s+=2;s+=Math.min(4,raw.split(/\r?\n/).filter(x=>x.trim().length>1).length/3);return s}
function parseBusinessCard(raw){const lines=raw.split(/\r?\n/).map(x=>x.replace(/[|｜]/g,' ').replace(/\s+/g,' ').trim()).filter(x=>x.length>1),joined=lines.join(' '),email=(joined.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||'',urls=joined.match(/(?:https?:\/\/|www\.)[^\s]+/ig)||[],website=urls.find(x=>!x.includes('@'))||'',pm=joined.match(/(?:\+?\d[\d\s().-]{7,}\d)/g)||[],phones=[...new Set(pm.map(x=>x.trim()).filter(x=>x.replace(/\D/g,'').length>=8))],mobile=phones.find(x=>/09\d{8}|9\d{8}/.test(x.replace(/\D/g,'')))||phones[0]||'',phone2=phones.find(x=>x!==mobile)||'',companyRx=/(股份有限公司|有限公司|公司|集團|基金會|協會|公會|局|處|部|中心|研究院|工程顧問|科技|建設|銀行|醫院|大學|Inc\.?|Ltd\.?|Corp\.?|Company|Group|Consult)/i,titleRx=/(董事長|總經理|副總|協理|經理|副理|處長|科長|組長|主任|工程師|顧問|專員|教授|Project Manager|Product Manager|Manager|Director|Engineer|Consultant|President|CEO|CTO|CFO|VP)/i,addressRx=/(台灣|臺灣|台北|臺北|新北|桃園|新竹|台中|臺中|彰化|嘉義|台南|臺南|高雄|宜蘭|花蓮|市|縣|區|鄉|鎮|路|街|巷|號|Taiwan|Taipei|Taoyuan|Hsinchu|Taichung|Kaohsiung)/i,company=lines.find(x=>companyRx.test(x))||'',title=lines.find(x=>titleRx.test(x)&&x!==company)||'',address=lines.find(x=>addressRx.test(x)&&/\d/.test(x)&&x!==mobile&&x!==phone2)||'';let name=lines.find(x=>/^[\u3400-\u9fff·]{2,5}$/.test(x)&&!companyRx.test(x)&&!titleRx.test(x));if(!name)name=lines.find(x=>/^[A-Z][A-Za-z.'-]+(?:\s+[A-Z][A-Za-z.'-]+){1,2}$/.test(x));if(!name)name=lines.find(x=>x.length>=2&&x.length<=18&&!/[\d@]/.test(x)&&!companyRx.test(x)&&!titleRx.test(x)&&!addressRx.test(x))||'';return{name,company,title,mobile,phone:phone2,email,website:website.replace(/[),.;]+$/,''),address}}
function applyOcrFields(x){Object.entries(x).forEach(([k,v])=>{if(v&&$(k)&&!$(k).value.trim())$(k).value=v});if(x.title||x.website||x.address)$('advancedDetails').open=true}
async function recognizeCardImage(dataUrl,onProgress){await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js',()=>!!window.Tesseract);const preview=await dataUrlCanvas(dataUrl,1250),ocrImage=preview.toDataURL('image/jpeg',.88),r=await Tesseract.recognize(ocrImage,'chi_tra+eng',{logger:m=>{if(onProgress&&m.status==='recognizing text')onProgress(m.progress||0)}}),raw=(r.data&&r.data.text?r.data.text:'').trim(),confidence=(r.data&&Number.isFinite(r.data.confidence)?r.data.confidence:0);return{raw,confidence,fields:parseBusinessCard(raw)}}
async function runOCR(){if(ocrBusy||!$('photoData').value)return;ocrBusy=true;$('ocrBtn').disabled=true;setOcrProgress(.08,'快速辨識中…');try{const out=await recognizeCardImage($('photoData').value,p=>setOcrProgress(.12+p*.84,'辨識 '+Math.round(p*100)+'%'));$('ocrRawText').value=out.raw;$('rawOcrText').textContent=out.raw;$('rawOcrDetails').classList.toggle('hidden',!out.raw);applyOcrFields(out.fields);setOcrProgress(1,'完成');toast(out.confidence>=60?'名片辨識完成':'已先填入可辨識資料，低信心欄位請快速確認')}catch(e){console.error(e);toast('辨識暫時失敗，照片已保留，可直接手動補資料')}finally{ocrBusy=false;$('ocrBtn').disabled=false;setTimeout(()=>$('ocrProgress').classList.add('hidden'),1000)}}
async function enqueuePhotoToInbox(file,source={kind:'photo',app:'相簿'}){if(!file)return null;if(file.size>20*1024*1024){toast('圖片太大，請選較小的照片');return null}try{const d=await compress(file,1600,.86),item={id:uid(),originalPhotoData:d,photoData:d,cropMeta:{cropped:false},ocrRawText:'',extracted:{},status:'queued',source:Object.assign({fileName:file.name||'',importedAt:nowIso()},source),createdAt:nowIso(),updatedAt:nowIso()};await inboxPut(item);await renderScanInbox();setTimeout(processScanQueue,120);return item}catch(e){console.error(e);toast('這張照片沒有成功收下，請再試一次');return null}}
