function vcard(c){return ['BEGIN:VCARD','VERSION:3.0','FN:'+(c.name||''),c.company?'ORG:'+c.company:'',c.title?'TITLE:'+c.title:'',c.mobile?'TEL;TYPE=CELL:'+c.mobile:'',c.phone?'TEL;TYPE=WORK:'+c.phone:'',c.email?'EMAIL:'+c.email:'',c.website?'URL:'+safeUrl(c.website):'',c.address?'ADR;TYPE=WORK:;;'+c.address+';;;;':'',c.notes?'NOTE:'+c.notes.replace(/\n/g,'\\n'):'','END:VCARD'].filter(Boolean).join('\r\n')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},900)}
async function shareVcard(c){const blob=new Blob([vcard(c)],{type:'text/vcard'}),file=new File([blob],(c.name||'contact')+'.vcf',{type:'text/vcard'});try{if(navigator.canShare&&navigator.canShare({files:[file]}))await navigator.share({title:c.name,text:[c.company,c.title].filter(Boolean).join(' · '),files:[file]});else download(blob,file.name)}catch(e){if(e.name!=='AbortError')toast('分享失敗')}}
