async function buildBackupPayload(){return{app:'little-days-cards',version:VERSION,schemaVersion:SCHEMA_VERSION,exportedAt:nowIso(),myCard:getMyCard(),settings:{activeFilter,sort:$('sortSelect')?$('sortSelect').value:'updated-desc'},contacts,scanInbox:await inboxAll(),importBatches:await batchAll()}}
async function emitBackup({share=true,prefix='人脈名片完整備份',record=true}={}){const x=await buildBackupPayload(),fileName=prefix+'_'+today()+'.json',blob=new Blob([JSON.stringify(x,null,2)],{type:'application/json'}),file=new File([blob],fileName,{type:'application/json'});let completed=false;try{if(share&&navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({title:'人脈名片備份',text:'建議儲存到 iCloud Drive／Google Drive',files:[file]});completed=true}else{download(blob,fileName);completed=true}}catch(e){if(e.name!=='AbortError'){download(blob,fileName);completed=true}}if(completed&&record){setBackupMeta({lastBackupAt:nowIso(),fileName,contactCount:contacts.length,photoCount:contacts.filter(x=>x.photoData).length,inboxCount:x.scanInbox.length,schemaVersion:SCHEMA_VERSION});renderBackupStatus(x.scanInbox);toast('完整備份已建立')}return completed}
