async function restoreFile(file,mode=restoreMode){if(!file)return;try{const x=JSON.parse(await file.text());if(x.app&&x.app!=='little-days-cards')throw new Error('app');if(!Array.isArray(x.contacts))throw new Error('contacts');if(mode==='replace'){if(!confirm('整份取代會先下載一份「恢復前備份」，再清除目前資料。\n\n確定繼續嗎？'))return;await emitBackup({share:false,prefix:'恢復前備份',record:false});await dbClear();await inboxClear();await batchClear()}for(const raw of x.contacts){const contact=Object.assign({},raw,{id:raw.id||uid(),interactions:interactions(raw),createdAt:raw.createdAt||nowIso(),updatedAt:raw.updatedAt||nowIso()});if(mode==='merge'){const dup=findDuplicate(contact);await dbPut(dup?mergeContact(dup,contact):contact)}else await dbPut(contact)}if(Array.isArray(x.scanInbox)){for(const item of x.scanInbox)await inboxPut(Object.assign({},item,{id:item.id||uid(),status:item.status==='processing'?'queued':(item.status||'queued'),createdAt:item.createdAt||nowIso(),updatedAt:nowIso()}))}if(Array.isArray(x.importBatches)){for(const b of x.importBatches)await batchPut(b)}if(x.myCard)localStorage.setItem(MY_CARD_KEY,JSON.stringify(x.myCard));await reload();closeDlg('backupDialog');toast(mode==='replace'?'已完整恢復備份':'已合併恢復 '+x.contacts.length+' 筆');setTimeout(processScanQueue,500)}catch(e){console.error(e);alert('這不是有效的人脈名片備份檔，或檔案內容已損壞。')}}
const csvCell=v=>'"'+(Array.isArray(v)?v.join('|'):String(v==null?'':v)).replace(/"/g,'""')+'"';
function exportCsv(){const h=['姓名','公司','職稱','部門','手機','電話','Email','通訊','網站','地址','場合','專案','標籤','下次追蹤','最愛','備註','互動次數','最後互動','建立時間','更新時間'],rows=contacts.map(c=>[c.name,c.company,c.title,c.department,c.mobile,c.phone,c.email,c.messenger,c.website,c.address,c.context,c.project,tags(c.tags),c.followUpDate,c.favorite?'是':'否',c.notes,interactions(c).length,(lastInteraction(c)||{}).date||'',c.createdAt,c.updatedAt]),csv='\ufeff'+[h].concat(rows).map(x=>x.map(csvCell).join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),'人脈名片_'+today()+'.csv');toast('CSV 已匯出')}

function parseVcards(text){return text.split(/(?=BEGIN:VCARD)/i).filter(x=>/BEGIN:VCARD/i.test(x)).map(block=>{const lines=block.replace(/\r\n[ \t]/g,'').split(/\r?\n/),get=key=>{const l=lines.find(x=>new RegExp('^'+key+'(?:;[^:]*)?:','i').test(x));return l?l.slice(l.indexOf(':')+1).replace(/\\n/g,'\n').trim():''},tels=lines.filter(x=>/^TEL/i.test(x)).map(x=>x.slice(x.indexOf(':')+1).trim());return{id:uid(),name:get('FN')||get('N').split(';').filter(Boolean).reverse().join(' '),company:get('ORG').replace(/;/g,' '),title:get('TITLE'),mobile:tels[0]||'',phone:tels[1]||'',email:get('EMAIL'),website:get('URL'),address:get('ADR').replace(/;/g,' ').replace(/\s+/g,' ').trim(),notes:get('NOTE'),department:'',messenger:'',context:'',project:'',tags:[],followUpDate:'',favorite:false,photoData:'',ocrRawText:'',interactions:[],createdAt:nowIso(),updatedAt:nowIso()}}).filter(x=>x.name)}
async function importVcfFiles(files){let n=0;for(const f of files){for(const c of parseVcards(await f.text())){const dup=findDuplicate(c);await dbPut(dup?mergeContact(dup,c):c);n++}}await reload();closeDlg('toolsDialog');toast('已匯入 '+n+' 位聯絡人')}



function openAiAssistant(){closeDlg('captureChoiceDialog');closeDlg('toolsDialog');aiFiles=[];aiPreparedImages=[];renderAiFiles();$('aiResultPaste').value='';$('apiCostAck').checked=false;$('continueApiBtn').disabled=true;openDlg('aiAssistantDialog')}
async function prepareAiAttachments(files){for(const file of files){aiFiles.push(file);if(file.type&&file.type.startsWith('image/')){const slot=aiPreparedImages.length;aiPreparedImages.push({loading:true,name:file.name});renderAiFiles();try{const original=await compress(file,1600,.88),crop=await fastAutoCropCard(original).catch(()=>({dataUrl:original,cropped:false}));aiPreparedImages[slot]={name:file.name,originalPhotoData:original,photoData:crop.dataUrl,cropped:!!crop.cropped}}catch(e){console.error(e);aiPreparedImages[slot]={name:file.name,error:true}}}else aiPreparedImages.push(null)}renderAiFiles()}
function renderAiFiles(){const box=$('aiAttachmentList');if(!box)return;box.innerHTML=aiFiles.length?aiFiles.map((f,i)=>{const p=aiPreparedImages[i],isImg=f.type&&f.type.startsWith('image/'),visual=isImg&&p&&p.photoData?'<img src="'+p.photoData+'" alt="">':'<span>'+(isImg?'▣':'▤')+'</span>',status=isImg?(p&&p.loading?'正在保留原圖與裁切…':p&&p.photoData?(p.cropped?'原始照片已保留 · 已自動裁切':'原始照片已保留 · 使用原圖'):'照片準備中'):(Math.max(1,Math.round(f.size/1024))+' KB');return '<div class="ai-file-chip '+(isImg?'image-file':'')+'"><div class="ai-file-visual">'+visual+'</div><div><strong>'+esc(f.name)+'</strong><small>'+esc(status)+'</small></div><button data-remove-ai-file="'+i+'" aria-label="移除">×</button></div>'}).join(''):'<div class="ai-empty-attachments">尚未加入檔案。可以一次選多張照片或多個檔案。</div>'}
function buildAiPrompt(){const context=$('aiContextText').value.trim(),names=aiFiles.map(f=>f.name);return [
'你是 Little Days 人脈 App 的 AI 整理助手。',
'請分析我附上的名片照片、PDF、Excel、CSV、vCard 或其他聯絡人資料。',
'任務：辨識每一位人物，理解欄位語意，而不是只做 OCR。不要猜；不確定就留空，並列入 needsConfirmation。',
context?'這批資料的補充情境：'+context:'',
names.length?'附件檔名：'+names.join('、'):'',
'',
'請只回傳一個 JSON 物件，不要加 Markdown code fence，不要加其他說明。格式必須是：',
'{',
'  "littleDaysPeopleImport": 1,',
'  "source": "請填你自己的 AI 名稱，例如 Claude",',
'  "summary": "簡短說明辨識結果",',
'  "contacts": [',
'    {',
'      "name": "",',
'      "company": "",',
'      "department": "",',
'      "title": "",',
'      "professionalTitles": [],',
'      "mobile": "",',
'      "phone": "",',
'      "email": "",',
'      "address": "",',
'      "website": "",',
'      "messenger": "",',
'      "context": "",',
'      "project": "",',
'      "tags": [],',
'      "notes": "",',
'      "confidence": {"name":"high","company":"high"},',
'      "needsConfirmation": []',
'    }',
'  ]',
'}',
'',
'規則：',
'1. 手機與公司電話要分開；台灣 09 開頭優先判定為 mobile。',
'2. 公司、部門、職稱、專業頭銜要分開。',
'3. tags 可以依名片內容與補充情境建議，但不要把推測寫進原始欄位。',
'4. 如果同一份檔案有多人，contacts 必須一人一筆。',
'5. 若同一人出現多次，可以合併明確相同的資料；不確定是否同一人則分開。',
'6. 日期／場合／專案若只來自我的補充情境，可以填入 context/project/notes，但不要虛構。'
].filter(Boolean).join('\n')}
async function shareFreeAi(){if(!aiFiles.length)return toast('先加入至少一張照片或一個檔案');const prompt=buildAiPrompt(),instruction=new File([prompt],'LittleDays_給AI的整理指令.txt',{type:'text/plain'}),shareFiles=[...aiFiles,instruction];try{if(navigator.canShare&&navigator.canShare({files:shareFiles})){await navigator.share({title:'Little Days 人脈整理',text:'請讀取附件中的 Little Days 整理指令並直接回傳 JSON。完成後請提醒我：複製全部結果，再回 Little Days 按「從剪貼簿直接回填」。',files:shareFiles});toast('分享選單已開啟；目前可直接選 Claude')}else{await navigator.clipboard.writeText(prompt);toast('整理指令已複製，請把附件與指令交給 AI App')}}catch(e){if(e.name!=='AbortError'){console.error(e);try{await navigator.clipboard.writeText(prompt);toast('分享失敗，已把整理指令複製到剪貼簿')}catch(_){toast('分享失敗，請稍後再試')}}}}
async function applyAiClipboard(){try{if(!navigator.clipboard||!navigator.clipboard.readText)throw new Error('clipboard unsupported');const text=await navigator.clipboard.readText();if(!text.trim())return toast('剪貼簿目前沒有內容');await applyAiPayloadText(text)}catch(e){console.error(e);const d=document.querySelector('.ai-manual-fallback');if(d)d.open=true;toast('iPhone 沒有允許讀剪貼簿，請改用手動貼上')}}
function stripJsonFence(text=''){let s=String(text).trim();s=s.replace(/^\s*```(?:json)?\s*/i,'').replace(/\s*```\s*$/,'').trim();const a=s.indexOf('{'),b=s.lastIndexOf('}');return a>=0&&b>a?s.slice(a,b+1):s}
function aiRawToContact(raw,provider='AI App'){const x=normalizeImportedObject(raw,{kind:'ai-bridge',app:provider,fileName:'AI 整理結果'});x.professionalTitles=Array.isArray(raw.professionalTitles)?raw.professionalTitles:[];if(x.professionalTitles.length){const extra=x.professionalTitles.join('／');x.title=[x.title,extra].filter(Boolean).join('／')}x.tags=[...new Set(tags(raw.tags).concat(tags(raw.suggestedTags||raw.aiTags||[])))];x.aiMeta={provider,mode:'free-bridge',confidence:raw.confidence||{},needsConfirmation:Array.isArray(raw.needsConfirmation)?raw.needsConfirmation:[],importedAt:nowIso()};x.source={kind:'ai-bridge',app:provider,fileName:'AI 整理結果',importedAt:nowIso()};x.derived=smartClassify(x);return x}
async function applyAiPayloadText(text){try{const payload=JSON.parse(stripJsonFence(text)),arr=Array.isArray(payload)?payload:Array.isArray(payload.contacts)?payload.contacts:(payload.contact?[payload.contact]:[]);if(!arr.length)throw new Error('no contacts');const provider=(payload&&payload.source)||'AI App',mapped=arr.map(raw=>aiRawToContact(raw,provider)),prepared=aiPreparedImages.filter(x=>x&&x.photoData);if(prepared.length===mapped.length)prepared.forEach((p,i)=>{mapped[i].photoData=p.photoData;mapped[i].originalPhotoData=p.originalPhotoData;mapped[i].cropMeta={cropped:p.cropped,source:'ai-attachment'}});if(mapped.length===1){const x=mapped[0];pendingAiMeta={source:x.source,derived:x.derived,aiMeta:x.aiMeta};resetForm();setMode(x.photoData?'edit-scan':'edit');['name','company','department','title','mobile','phone','email','address','website','messenger','context','project','notes'].forEach(k=>{if($(k))$(k).value=x[k]||''});$('tags').value=tags(x.tags).join(', ');if(x.photoData){$('photoData').value=x.photoData;$('originalPhotoData').value=x.originalPhotoData||x.photoData;$('photoPreview').innerHTML='<img src="'+x.photoData+'" alt="名片裁切照片">';$('photoPreserveStatus').classList.remove('hidden');$('photoPreserveStatus').innerHTML='<span>✓ 原始照片已保留</span><span>'+(x.originalPhotoData&&x.originalPhotoData!==x.photoData?'✓ 已自動裁切名片':'• 使用原始照片')+'</span>';$('removePhotoBtn').classList.remove('hidden');$('ocrBtn').classList.remove('hidden')}$('advancedDetails').open=!!(x.department||x.title||x.phone||x.address||x.website||x.context||x.project||x.tags.length);closeDlg('aiAssistantDialog');openDlg('editDialog');const n=(x.aiMeta.needsConfirmation||[]).length;toast(n?'AI 已回填；有 '+n+' 個欄位建議確認':'AI 已回填完成');return}const seen=new Set();importCandidates=mapped.map(contact=>{const st=candidateStatus(contact,seen);if((contact.aiMeta.needsConfirmation||[]).length&&st.status==='ready')return{id:uid(),contact,status:'issue',reason:'AI 建議確認：'+contact.aiMeta.needsConfirmation.join('、'),source:contact.source};return{id:uid(),contact,...st,source:contact.source}});importSourceFiles=['AI 整理結果'];importMappingNotes=[{field:'AI',header:'AI 結構化資料'}];closeDlg('aiAssistantDialog');openDlg('importDialog');renderImportPreview();toast('AI 已整理 '+mapped.length+' 位人脈')}catch(e){console.error(e);alert('無法解析這份 AI 結果。請確認有複製完整 JSON，或請 AI 依 Little Days 格式重新輸出。')}}
async function readAiResultFile(file){if(!file)return;try{await applyAiPayloadText(await file.text())}catch(e){console.error(e);toast('讀取 ChatGPT 結果失敗')}}

function openImportCenter(){closeDlg('captureChoiceDialog');closeDlg('toolsDialog');resetImportPreview();renderImportHistory();openDlg('importDialog')}
function resetImportPreview(){importCandidates=[];importMappingNotes=[];importSourceFiles=[];if($('importPreviewSection'))$('importPreviewSection').classList.add('hidden');if($('importCandidateList'))$('importCandidateList').innerHTML='';if($('mappingNotice'))$('mappingNotice').classList.add('hidden')}
function normalizedHeader(v){return norm(v).replace(/[\s_\-\/()（）.:：]+/g,'')}
const FIELD_ALIASES={
 name:['姓名','名字','name','fullname','contactname','中文姓名','displayname','fn'],
 company:['公司','公司名稱','機關','單位','organization','organisation','org','company','companyname','organizationname'],
 title:['職稱','職位','title','position','jobtitle','job','role'],
 department:['部門','部門單位','department','dept','division','team'],
 mobile:['手機','行動電話','mobile','mobilephone','cell','cellphone','cellular'],
 phone:['電話','公司電話','辦公室電話','tel','telephone','phone','workphone','officephone'],
 email:['email','電子郵件','mail','emailaddress','e-mail'],
 website:['網站','網址','website','web','url','homepage'],
 address:['地址','公司地址','address','workaddress','officeaddress'],
 messenger:['line','lineid','通訊','wechat','wechatid','teams'],
 notes:['備註','註記','memo','note','notes','remark','remarks'],
 tags:['標籤','分類','群組','tag','tags','category','categories','group'],
 context:['認識場合','場合','context','event','meeting'],
 project:['專案','計畫','project','projects']
};
function mapHeaders(headers){const mapping={},used=[];headers.forEach((h,i)=>{const nh=normalizedHeader(h);for(const [field,aliases] of Object.entries(FIELD_ALIASES)){if(mapping[field]==null&&aliases.some(a=>normalizedHeader(a)===nh)){mapping[field]=i;used.push({field,header:String(h)});break}}});return{mapping,used}}
function parseCsvRows(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(q){if(ch==='"'&&next==='"'){cell+='"';i++}else if(ch==='"')q=false;else cell+=ch}else if(ch==='"')q=true;else if(ch===','){row.push(cell);cell=''}else if(ch==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell.replace(/\r$/,''));if(row.some(x=>String(x).trim()))rows.push(row);return rows}
function guessSourceApp(fileName=''){const n=fileName.toLowerCase();if(n.includes('camcard'))return'CamCard';if(/(^|[-_ ])eight/.test(n)||n.includes('8card'))return'Eight';if(n.includes('hihello'))return'HiHello';if(n.includes('sansan'))return'Sansan';if(n.includes('covve'))return'Covve';if(n.includes('contacts')||n.includes('contact'))return'聯絡人匯出';return'其他 App'}
function smartClassify(x){const text=norm([x.company,x.title,x.department,x.notes].join(' ')),domain=[];let org='其他';if(/政府|市府|縣府|公所|交通局|工務局|建設局|警察局|環保局|教育局|公路局|交通部|內政部|經濟部|署(?:\s|$)/.test(text))org='公部門';else if(/顧問|consult|工程/.test(text))org='工程顧問';else if(/建設|開發|營造|construction|developer/.test(text))org='建設／開發';else if(/大學|學院|研究院|university|college/.test(text))org='學術研究';else if(/銀行|bank|金融|證券/.test(text))org='金融';else if(x.company)org='企業';
 if(/交通|運輸|transport|traffic|mobility/.test(text))domain.push('交通運輸');if(/道路|公路|road|highway/.test(text))domain.push('道路');if(/停車|parking/.test(text))domain.push('停車');if(/自行車|bike|bicycle/.test(text))domain.push('自行車');if(/都市|urban|city planning/.test(text))domain.push('都市規劃');if(/捷運|軌道|metro|rail/.test(text))domain.push('軌道運輸');
 return{organizationType:org,domainTags:[...new Set(domain)],method:'local-smart-rules',generatedAt:nowIso()}}
function contactKey(x){if(x.email)return'e:'+norm(x.email);const m=String(x.mobile||'').replace(/\D/g,'');if(m.length>=8)return'm:'+m;if(x.name&&x.company)return'nc:'+norm(x.name)+'|'+norm(x.company);return''}
function normalizeImportedObject(raw,source={}){const o={},entries=Object.entries(raw||{}),headers=entries.map(([k])=>k),mh=mapHeaders(headers);for(const [field,idx] of Object.entries(mh.mapping)){const key=headers[idx];o[field]=raw[key]==null?'':String(raw[key]).trim()}if(!o.name&&raw.name)o.name=String(raw.name);if(!o.company&&raw.company)o.company=String(raw.company);if(!o.email&&raw.email)o.email=String(raw.email);if(!o.mobile&&raw.mobile)o.mobile=String(raw.mobile);return Object.assign({id:uid(),name:'',company:'',title:'',department:'',mobile:'',phone:'',email:'',messenger:'',website:'',address:'',context:'',project:'',tags:[],followUpDate:'',favorite:false,notes:'',photoData:'',ocrRawText:'',interactions:[],createdAt:nowIso(),updatedAt:nowIso()},o,{tags:tags(o.tags),source:Object.assign({kind:'file',importedAt:nowIso()},source)})}
function candidateStatus(contact,seen){if(!contact.name)return{status:'issue',reason:'缺少姓名'};const key=contactKey(contact);if(key&&seen.has(key))return{status:'duplicate',reason:'匯入檔內重複'};if(key)seen.add(key);const dup=findDuplicate(contact);if(dup)return{status:'duplicate',reason:'與現有人脈重複',duplicateId:dup.id};return{status:'ready',reason:'可直接匯入'}}
function rowsToCandidates(rows,source){if(!rows.length)return{items:[],mapping:[]};const headers=rows[0].map(x=>String(x||'').trim()),mh=mapHeaders(headers),seen=new Set(),items=[];for(const row of rows.slice(1)){if(!row.some(x=>String(x||'').trim()))continue;const raw={};headers.forEach((h,i)=>raw[h]=row[i]??'');const contact=normalizeImportedObject(raw,source),st=candidateStatus(contact,seen);contact.derived=smartClassify(contact);items.push({id:uid(),contact,...st,source})}return{items,mapping:mh.used}}
async function loadXlsx(){await loadScript('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js',()=>!!window.XLSX)}
async function parseImportFile(file){
 const ext=(file.name.split('.').pop()||'').toLowerCase(),source={fileName:file.name,app:guessSourceApp(file.name),kind:ext||file.type};
 if(file.type.startsWith('image/')){const item=await enqueuePhotoToInbox(file,{kind:'photo-import',app:'相簿匯入',fileName:file.name});return{photo:item?1:0,items:[],mapping:[]}}
 if(ext==='vcf'){const seen=new Set(),items=parseVcards(await file.text()).map(contact=>{contact.source=Object.assign({importedAt:nowIso()},source);contact.derived=smartClassify(contact);const st=candidateStatus(contact,seen);return{id:uid(),contact,...st,source}});return{items,mapping:[{field:'vCard',header:'標準 vCard 欄位'}]}}
 if(ext==='csv'||file.type.includes('csv'))return rowsToCandidates(parseCsvRows((await file.text()).replace(/^\uFEFF/,'')),source);
 if(ext==='xlsx'||ext==='xls'){await loadXlsx();const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),items=[],mapping=[];for(const name of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,raw:false,defval:''});const out=rowsToCandidates(rows,Object.assign({},source,{sheet:name}));items.push(...out.items);mapping.push(...out.mapping)}return{items,mapping}}
 if(ext==='json'){const x=JSON.parse(await file.text()),arr=Array.isArray(x)?x:Array.isArray(x.contacts)?x.contacts:Array.isArray(x.data)?x.data:[];if(!arr.length)return{items:[{id:uid(),status:'issue',reason:'JSON 找不到聯絡人陣列',contact:{name:'JSON：'+file.name},source}],mapping:[]};const seen=new Set(),items=arr.map(raw=>{const contact=normalizeImportedObject(raw,source);if(raw.photoData)contact.photoData=raw.photoData;if(Array.isArray(raw.interactions))contact.interactions=raw.interactions;contact.derived=smartClassify(contact);const st=candidateStatus(contact,seen);return{id:uid(),contact,...st,source}});return{items,mapping:[]}}
 if(ext==='pdf')return{items:[{id:uid(),status:'issue',reason:'PDF 已接收；需 ChatGPT Vision 後端才能智慧拆分名片',contact:{name:'PDF：'+file.name},source}],mapping:[]};
 return{items:[{id:uid(),status:'issue',reason:'目前尚未支援這個檔案格式',contact:{name:file.name},source}],mapping:[]}
}
function renderImportPreview(){const sec=$('importPreviewSection');if(!sec)return;const total=importCandidates.length,ready=importCandidates.filter(x=>x.status==='ready').length,dups=importCandidates.filter(x=>x.status==='duplicate').length,issues=importCandidates.filter(x=>x.status==='issue').length;sec.classList.toggle('hidden',total===0);$('importTotalCount').textContent=total;$('importReadyCount').textContent=ready;$('importDuplicateCount').textContent=dups;$('importIssueCount').textContent=issues;$('importPreviewTitle').textContent=importSourceFiles.length>1?'多檔匯入預覽':(importSourceFiles[0]||'匯入預覽');const uniqueMap=[...new Map(importMappingNotes.map(x=>[(x.header||'')+'|'+x.field,x])).values()];const notice=$('mappingNotice');if(uniqueMap.length){notice.classList.remove('hidden');notice.innerHTML='<strong>智慧欄位對應</strong><span>'+uniqueMap.slice(0,12).map(x=>esc(x.header)+' → '+esc(x.field)).join('　')+(uniqueMap.length>12?'…':'')+'</span>'}else notice.classList.add('hidden');$('importCandidateList').innerHTML=importCandidates.slice(0,100).map(x=>'<article class="import-candidate '+esc(x.status)+'"><div class="candidate-avatar">'+esc(initials(x.contact.name||'?'))+'</div><div class="candidate-copy"><strong>'+esc(x.contact.name||'未命名資料')+'</strong><span>'+esc([x.contact.company,x.contact.title].filter(Boolean).join(' · ')||x.source.fileName||'')+'</span><small>'+esc((x.contact.derived&&[x.contact.derived.organizationType].concat(x.contact.derived.domainTags||[]).filter(Boolean).join('／'))||x.reason||'')+'</small></div><div class="candidate-status">'+(x.status==='ready'?'✓':x.status==='duplicate'?'重複':'!')+'</div></article>').join('');$('confirmImportBtn').disabled=ready===0;$('confirmImportBtn').textContent=ready?'匯入 '+ready+' 筆可用資料':'沒有可直接匯入的資料'}
async function processImportFiles(files){if(!files.length)return;resetImportPreview();importSourceFiles=files.map(f=>f.name);let photos=0;for(const file of files){try{const out=await parseImportFile(file);photos+=out.photo||0;importCandidates.push(...(out.items||[]));importMappingNotes.push(...(out.mapping||[]))}catch(e){console.error(e);importCandidates.push({id:uid(),status:'issue',reason:'檔案解析失敗',contact:{name:file.name},source:{fileName:file.name,app:guessSourceApp(file.name)}})}}renderImportPreview();if(photos){await renderScanInbox();toast('已把 '+photos+' 張照片送進待整理匣')}if(importCandidates.length)$('importPreviewSection').scrollIntoView({behavior:'smooth',block:'start'})}
async function confirmImport(){const ready=importCandidates.filter(x=>x.status==='ready');if(!ready.length)return;const batchId=uid(),createdIds=[];for(const item of ready){const contact=Object.assign({},item.contact,{id:item.contact.id||uid(),source:Object.assign({},item.contact.source,{importBatchId:batchId})});await dbPut(contact);createdIds.push(contact.id)}const batch={id:batchId,createdAt:nowIso(),files:[...importSourceFiles],count:createdIds.length,createdIds,status:'active'};await batchPut(batch);await reload();importCandidates=importCandidates.filter(x=>x.status!=='ready');renderImportPreview();await renderImportHistory();toast('已匯入 '+createdIds.length+' 位人脈')}
async function renderImportHistory(){if(!$('importHistoryList'))return;const batches=(await batchAll()).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,8);$('importHistoryList').innerHTML=batches.length?batches.map(b=>'<article class="import-history-item"><div><strong>'+esc((b.files||[]).join('、')||'匯入批次')+'</strong><span>'+esc(new Date(b.createdAt).toLocaleString('zh-TW'))+' · '+b.count+' 筆</span></div>'+(b.status==='active'?'<button data-rollback-batch="'+esc(b.id)+'">復原</button>':'<span class="rolled-back">已復原</span>')+'</article>').join(''):'<div class="timeline-empty">還沒有檔案匯入紀錄。</div>'}
async function rollbackImportBatch(id){const batch=await batchGet(id);if(!batch||batch.status!=='active')return;if(!confirm('要復原這次匯入的 '+batch.count+' 筆資料嗎？\n\n只會刪除這個批次新建立的人脈。'))return;for(const cid of batch.createdIds||[])await dbDelete(cid);batch.status='rolledback';batch.rolledBackAt=nowIso();await batchPut(batch);await reload();await renderImportHistory();toast('已復原這次匯入')}


function categoryStats(){const tagMap=new Map(),companyMap=new Map();for(const c of contacts){for(const v of categoryValues(c))tagMap.set(v,(tagMap.get(v)||0)+1);if(c.company)companyMap.set(c.company,(companyMap.get(c.company)||0)+1)}const sorter=(a,b)=>b[1]-a[1]||String(a[0]).localeCompare(String(b[0]),'zh-Hant');return{tags:[...tagMap].sort(sorter),companies:[...companyMap].sort(sorter)}}
function openCategories(){closeDlg('toolsDialog');renderCategories();openDlg('categoryDialog')}
function renderCategories(){const s=categoryStats();$('categoryAllCount').textContent=contacts.length;$('categoryAllBtn').classList.toggle('active',!activeCategory);$('categoryList').innerHTML=s.tags.length?s.tags.map(([name,count])=>'<button class="category-row '+(activeCategory==='tag:'+name?'active':'')+'" data-category-key="tag:'+esc(name)+'"><span>'+esc(name)+'</span><b>'+count+'</b></button>').join(''):'<div class="timeline-empty">還沒有標籤或 AI 分類。</div>';$('companyCategoryList').innerHTML=s.companies.length?s.companies.slice(0,40).map(([name,count])=>'<button class="category-row '+(activeCategory==='company:'+name?'active':'')+'" data-category-key="company:'+esc(name)+'"><span>'+esc(name)+'</span><b>'+count+'</b></button>').join(''):'<div class="timeline-empty">還沒有公司資料。</div>'}
function renderHomeCategories(){const rail=$('homeCategoryRail');if(!rail)return;const s=categoryStats(),items=[...s.tags.slice(0,10).map(([name,count])=>({key:'tag:'+name,name,count})),...s.companies.slice(0,8).map(([name,count])=>({key:'company:'+name,name,count}))];rail.innerHTML='<button class="home-category-chip '+(!activeCategory?'active':'')+'" data-home-category="">全部 <b>'+contacts.length+'</b></button>'+items.map(x=>'<button class="home-category-chip '+(activeCategory===x.key?'active':'')+'" data-home-category="'+esc(x.key)+'">'+esc(x.name)+' <b>'+x.count+'</b></button>').join('')}
function selectCategory(key=''){activeCategory=key;activeFilter='all';document.querySelectorAll('.filter-chip').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));closeDlg('categoryDialog');render();window.scrollTo({top:0,behavior:'smooth'})}
function renderAlphabet(list){const rail=$('alphabetRail');if(!rail)return;const keys=[...new Set(list.map(c=>alphaKey(c.name)))],order='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').filter(x=>keys.includes(x));if(keys.includes('#'))order.push('#');rail.innerHTML=order.map(k=>'<button data-alpha-jump="'+k+'">'+k+'</button>').join('');rail.classList.toggle('hidden',order.length<2)}
function jumpAlpha(k){$('sortSelect').value='name-asc';render();requestAnimationFrame(()=>{const safe=window.CSS&&CSS.escape?CSS.escape(k):k.replace(/"/g,'');const el=document.querySelector('.contact-card[data-alpha="'+safe+'"]');if(el)el.scrollIntoView({behavior:'smooth',block:'center'})})}
function duplicateGroups(){const maps={email:new Map(),mobile:new Map(),nameCompany:new Map()};for(const c of contacts){const e=norm(c.email),m=String(c.mobile||'').replace(/\D/g,''),nc=c.name&&c.company?norm(c.name)+'|'+norm(c.company):'';if(e){if(!maps.email.has(e))maps.email.set(e,[]);maps.email.get(e).push(c)}if(m.length>=8){if(!maps.mobile.has(m))maps.mobile.set(m,[]);maps.mobile.get(m).push(c)}if(nc){if(!maps.nameCompany.has(nc))maps.nameCompany.set(nc,[]);maps.nameCompany.get(nc).push(c)}}const seen=new Set(),groups=[];for(const map of Object.values(maps)){for(const arr of map.values()){if(arr.length<2)continue;const ids=arr.map(x=>x.id).sort(),key=ids.join('|');if(!seen.has(key)){seen.add(key);groups.push(arr)}}}return groups}
function isIncomplete(c){return !c.company||!(c.mobile||c.phone||c.email)}
function isStale(c){const last=lastInteraction(c),base=last&&last.date?new Date(last.date+'T12:00:00'):new Date(c.updatedAt||c.createdAt||0);return base.getTime()>0&&Date.now()-base.getTime()>365*864e5}
function healthData(){const confirm=contacts.filter(c=>c.aiMeta&&Array.isArray(c.aiMeta.needsConfirmation)&&c.aiMeta.needsConfirmation.length),incomplete=contacts.filter(isIncomplete),stale=contacts.filter(isStale),duplicates=duplicateGroups(),ids=new Set([...confirm,...incomplete,...stale].map(x=>x.id));duplicates.flat().forEach(x=>ids.add(x.id));return{confirm,incomplete,stale,duplicates,total:ids.size}}
function renderManagementHints(){const h=healthData();if($('healthHint'))$('healthHint').textContent=h.total?h.total+' 位需要留意':'目前資料很乾淨';if($('healthBadge')){$('healthBadge').textContent=h.total;$('healthBadge').classList.toggle('hidden',!h.total)}}
function openHealth(){closeDlg('toolsDialog');renderHealth('all');openDlg('healthDialog')}
function healthSectionButton(type,label,count){return '<button data-health-type="'+type+'"><strong>'+count+'</strong><span>'+label+'</span></button>'}
function renderHealth(type='all'){const h=healthData();$('healthHeroTitle').textContent=h.total?'有 '+h.total+' 位值得看一下':'資料很乾淨';$('healthHeroText').textContent=h.total?'不用整理全部，只處理下面例外。':'目前沒有重複、缺資料或 AI 待確認。';$('healthSummary').innerHTML=healthSectionButton('confirm','AI 待確認',h.confirm.length)+healthSectionButton('duplicate','疑似重複',h.duplicates.length)+healthSectionButton('incomplete','資料不完整',h.incomplete.length)+healthSectionButton('stale','久未聯絡',h.stale.length);let items=[];if(type==='confirm'||type==='all')items.push(...h.confirm.map(c=>({c,label:'AI 待確認 '+(c.aiMeta.needsConfirmation||[]).join('、'),confirm:true})));if(type==='incomplete'||type==='all')items.push(...h.incomplete.map(c=>({c,label:!c.company?'缺公司資訊':'缺聯絡方式'})));if(type==='stale'||type==='all')items.push(...h.stale.map(c=>({c,label:'超過一年沒有更新／互動'})));if(type==='duplicate'||type==='all')h.duplicates.forEach(g=>items.push({group:g,label:'疑似同一人：'+g.map(x=>x.name).join(' / ')}));const seen=new Set();items=items.filter(x=>{const k=x.group?'g:'+x.group.map(y=>y.id).sort().join('|'):'c:'+x.c.id+'|'+x.label;if(seen.has(k))return false;seen.add(k);return true});$('healthDetailList').innerHTML=items.length?items.map(x=>x.group?'<article class="health-item duplicate"><span class="health-mark">≋</span><div><strong>'+esc(x.label)+'</strong><small>'+esc(x.group.map(y=>[y.company,y.email||y.mobile].filter(Boolean).join(' · ')).join('｜'))+'</small></div><button data-contact-id="'+esc(x.group[0].id)+'">查看</button></article>':'<article class="health-item '+(x.confirm?'needs-confirm':'')+'"><span class="health-mark">!</span><div><strong>'+esc(x.c.name)+'</strong><small>'+esc(x.label)+' · '+esc(x.c.company||'未填公司')+'</small></div><div class="health-actions">'+(x.confirm?'<button class="confirm-ok" data-confirm-ai-id="'+esc(x.c.id)+'">確認無誤</button>':'')+'<button data-contact-id="'+esc(x.c.id)+'">查看</button></div></article>').join(''):'<div class="health-clean">✓ 這一類目前沒有需要處理的項目</div>'}

function getMyCard(){try{return JSON.parse(localStorage.getItem(MY_CARD_KEY)||'{}')}catch(e){return{}}}
function setMyCard(c){localStorage.setItem(MY_CARD_KEY,JSON.stringify(c))}
function fillMyCard(){const c=getMyCard();$('myName').value=c.name||'';$('myCompany').value=c.company||'';$('myTitle').value=c.title||'';$('myMobile').value=c.mobile||'';$('myEmail').value=c.email||'';$('myWebsite').value=c.website||'';renderMyCard(c)}
function myCardFromForm(){return{name:$('myName').value.trim(),company:$('myCompany').value.trim(),title:$('myTitle').value.trim(),mobile:$('myMobile').value.trim(),email:$('myEmail').value.trim(),website:$('myWebsite').value.trim()}}
async function loadQrLib(){await loadScript('https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.min.js',()=>!!window.qrcode)}
async function renderMyCard(c){$('myCardInitials').textContent=initials(c.name||'我');$('myCardPreviewName').textContent=c.name||'設定你的名片';$('myCardPreviewMeta').textContent=[c.company,c.title].filter(Boolean).join(' · ')||'分享時不用再交換紙本名片';$('qrBox').innerHTML='<span>QR</span>';if(!c.name)return;try{await loadQrLib();const qr=qrcode(0,'M');qr.addData(vcard(c));qr.make();$('qrBox').innerHTML=qr.createImgTag(4,0)}catch(e){console.error(e)}}
async function saveMyCard(e){e.preventDefault();const c=myCardFromForm();setMyCard(c);await renderMyCard(c);toast('我的名片已儲存')}
async function shareMyCard(){const c=getMyCard();if(!c.name)return toast('先填姓名並儲存我的名片');await shareVcard(c)}

function startVoice(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return toast('這台瀏覽器暫不支援語音辨識');const r=new R();r.lang='zh-TW';r.interimResults=false;r.maxAlternatives=1;$('voiceNoteBtn').textContent='●';r.onresult=e=>{const t=e.results[0][0].transcript.trim();$('notes').value=[$('notes').value.trim(),t].filter(Boolean).join(' ')};r.onerror=()=>toast('語音辨識沒有成功');r.onend=()=>$('voiceNoteBtn').textContent='🎙';r.start()}
async function seedDemo(){const a=[{name:'陳怡君',company:'新北市政府',title:'科長',department:'交通規劃科',mobile:'0912-345-678',email:'yijun@example.gov.tw',context:'專案會議',project:'自行車路網',tags:['公部門','新北','自行車'],followUpDate:today(),favorite:true,notes:'關心轉乘節點與斷鏈改善。',interactions:[{id:uid(),date:today(),type:'會議',note:'討論汐科周邊轉乘與斷鏈改善方向。'}]},{name:'林志宏',company:'遠見工程顧問',title:'協理',mobile:'0933-222-111',email:'jhlin@example.com',context:'研討會',project:'交流道改善',tags:['顧問','道路'],favorite:false,notes:'後續可討論綜規合作。',interactions:[]},{name:'Amy Wang',company:'Urban Mobility Lab',title:'Project Manager',email:'amy@example.com',context:'論壇',tags:['國際','Mobility'],favorite:false,notes:'英文聯繫。',interactions:[]}];for(const d of a)await dbPut(Object.assign({id:uid(),photoData:'',phone:'',messenger:'',website:'',address:'',department:d.department||'',ocrRawText:'',createdAt:nowIso(),updatedAt:nowIso()},d));await reload();toast('已載入示範資料')}
function setFilter(f){activeFilter=f;activeCategory='';document.querySelectorAll('.filter-chip').forEach(b=>b.classList.toggle('active',b.dataset.filter===f));document.querySelectorAll('.nav-item[data-nav]').forEach(b=>b.classList.remove('active'));if(f==='all')document.querySelector('[data-nav="contacts"]')?.classList.add('active');if(f==='favorite')document.querySelector('[data-nav="favorites"]')?.classList.add('active');if(f==='followup')document.querySelector('[data-nav="followup"]')?.classList.add('active');render();window.scrollTo({top:0,behavior:'smooth'})}

